// Мой первый JavaScript-код
console.log("Привет, мир!");

// Выводим число
console.log(100);

/*
Это многострочный
комментарий
*/

let name = "Али";
let age = 18;
const city = "Душанбе";
let isStudent = true;

console.log(name);
console.log(age);
console.log(city);
console.log(isStudent);
console.log(typeof age);

let a = 10;
let b = 5;

console.log(a + b);
console.log(a - b);
console.log(a * b);
console.log(a / b);
console.log(a % b);

console.log(a > b);
console.log(a === b);
console.log(a > 5 && b < 10);

let age = 18;

if (age >= 18) {
  console.log("Доступ разрешён");
} else {
  console.log("Доступ запрещён");
}

let day = 2;

switch (day) {
  case 1:
    console.log("Понедельник");
    break;
  case 2:
    console.log("Вторник");
    break;
  default:
    console.log("Другой день");
}

// Цикл for
for (let i = 1; i <= 5; i++) {
  console.log(i);
}

// Цикл while
let number = 1;

while (number <= 3) {
  console.log(number);
  number++;
}

function sayHello() {
  console.log("Привет!");
}

sayHello();

function sum(a, b) {
  return a + b;
}

console.log(sum(5, 3));

const multiply = (a, b) => a * b;
console.log(multiply(4, 2));

const fruits = ["Яблоко", "Банан", "Апельсин"];

console.log(fruits[0]);
console.log(fruits.length);

fruits.push("Киви");
console.log(fruits);

fruits.pop();
console.log(fruits);

const user = {
  name: "Али",
  age: 18,
  city: "Душанбе"
};

console.log(user.name);
console.log(user["age"]);

user.age = 19;
user.job = "Developer";

console.log(user);

delete user.city;

const numbers = [1, 2, 3, 4, 5];

numbers.forEach(number => {
  console.log(number);
});

const doubled = numbers.map(number => number * 2);
console.log(doubled);

const evenNumbers = numbers.filter(number => number % 2 === 0);
console.log(evenNumbers);

const found = numbers.find(number => number > 3);
console.log(found);

console.log(numbers.includes(3));
